body:
Here is a simplified repro case:

``` js
var condition = 1;
var cases = {
  a: 1,
  b: 2,
};

switch (condition) {
  case cases.a:
    break;
  case cases.b:
    break;
}
```

issue.body:
As of 0.17.0, the new `no-duplicate-case` rule incorrectly flags the following `case` constructs:

```
var MSGS = {
    hello: 'hi',
    goodbye: 'bye'
};

function lookupMessage(msg) {

    switch (msg) {
        case MSGS.hello:
            return 'hi there';
        case MSGS.goodbye:
            return 'catch ya later';
    }
}

lookupMessage('hi');
```

The following code:

``` javascript
switch(method) {
    case HttpMethod.Get:
        // handle GET
        break;
    case HttpMethod.Put:
        // handle PUT
        break;
}
```

reports "Duplicate case label" error. This is due to `getHash` implementation that's aware only about test identifier, but not the actual expression value:

``` javascript
function getHash(test) {
        if (test.type === "Literal") {
            return test.type + typeof test.value + test.value;
        } else if (test.type === "Identifier") {
            return test.type + typeof test.name + test.name;
        }
    }
```

Test case : 
1. Create the file foo.js (below)
2. Run eslint on this file (the `no-duplicate-case` should be enabled)

Expected result: There should be no error

Actual result: error with the `no-duplicate-case` rule

Using Eslint 0.17.0

foo.js : 

``` javascript
/* eslint no-console: 0 */
/* global console: 1 */
var STATUSES = {
    FOO: 42,
    BAR: 43
};
var b = 42;

switch (b) {
    case STATUSES.FOO:
        console.log("foo");
        break;
    case STATUSES.BAR:
        console.log("bar");
        break;
}
```

Florent

The `getHash` function of the `no-duplicate-case` rule does not include CallExpressions so the rule will report false positives when using function calls in case statements.

Some examples:

```
var a = 1,
    f = function(b) {
        return b ? {
            p1: 1
        } : {
            p1: 2
        };
    };

switch (a) {
    case f(true).p1:
        break;
    case f(true, false).p1:
        break;
    default:
        break;
}
```

```
var a = 1,
    f1 = function() {
        return {
            p1: 1
        }
    },
    f2 = function() {
        return {
            p1: 2
        }
    };

switch (a) {
    case f1().p1:
        break;
    case f2().p1:
        break;
    default:
        break;
}
```

```
var a = 1,
    f = function(s) {
        return {
            p1: s
        }
    };

switch (a) {
    case f(a + 1).p1:
        break;
    case f(a + 2).p1:
        break;
    default:
        break;
}
```

Related issue: https://github.com/eslint/eslint/issues/2038
